Import ListNotations.
Open Scope bv_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).

(* [comment removed for export] *)
Definition OCF (m : word -> option byte) (s : Z) (ret : word) (regs : bvmap 5 word) (fr : bvmap 5 word) : word -> option byte :=
  wbytes (wbytes (wbytes (wbytes (wbytes (wbytes (wbytes (wbytes m
    (Z_to_bv 64 (s - 8)) (word_to_le_bytes 8 ret))
    (Z_to_bv 64 (s - 16)) (word_to_le_bytes 8 (getr regs 8)))
    (Z_to_bv 64 (s - 24)) (word_to_le_bytes 8 (getr regs 9)))
    (Z_to_bv 64 (s - 32)) (word_to_le_bytes 8 (getr regs 18)))
    (Z_to_bv 64 (s - 40)) (word_to_le_bytes 8 (getr regs 19)))
    (Z_to_bv 64 (s - 48)) (word_to_le_bytes 8 (getr regs 20)))
    (Z_to_bv 64 (s - 56)) (word_to_le_bytes 8 (reg_get fr 8)))
    (Z_to_bv 64 (s - 64)) (word_to_le_bytes 8 (reg_get fr 9)).
(* [comment removed for export] *)
Definition OCP (m : word -> option byte) (s : Z) (v : word) : word -> option byte := wbytes m (Z_to_bv 64 (s - 88)) (word_to_le_bytes 8 v).
(* [comment removed for export] *)
Definition OCW (m : word -> option byte) (pup plf : Z) (b0 b1 : list byte) : word -> option byte :=
  wbytes (wbytes m (Z_to_bv 64 pup) b0) (Z_to_bv 64 plf) b1.

Ltac fpn := cbn [fp_regs fp_csr].
Ltac fsgn F D := chain_step; [ reflexivity | eapply fpv_step_fsgnj; [exact F | reflexivity | exact D] | step_simpl ]; fpn.

Section Segs.
Variable rom : word -> option byte.
#[local] Notation "'u'" := bv_unsigned (only parsing).
(* [comment removed for export] *)
#[local] Instance oc_fxd : FPState | 100 := mkFP bvmap_empty (Z_to_bv 32 0).
Ltac sok_in SOK :=
  store_ok_peel;
  first [ exact SOK
        | eapply store_ok_sub; [ | exact SOK | | ]; rewrite ?length_N_to_le_bytes, ?u_Z2bv by lia; cbn [Z.of_nat Pos.of_succ_nat Pos.succ]; lia ].
Ltac fsd F D aa SOK := chain_step; [ reflexivity | eapply fp_step_fsd with (a := aa); [exact F | reflexivity | exact D | gres; imm_norm; addr_tac | sok_in SOK] | step_simpl ]; fpn.
Ltac fld F D aa bb R := chain_step; [ reflexivity | eapply fp_step_fld with (a := aa) (bs := bb); [exact F | reflexivity | exact D | gres; imm_norm; addr_tac | exact R] | step_simpl ]; fpn.

(* [comment removed for export] *)
Lemma oc_P : forall fr cs regs m (s pixs pup plf prot dbg d : Z) (ret : word),
  (96 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= pixs)%Z -> (pixs + 64 <= 2 ^ 64)%Z -> (pixs + 64 <= s - 96 \/ s <= pixs)%Z -> (0 <= d < 2 ^ 31)%Z ->
  rdn SEGS m (Z_to_bv 64 (pixs + 8)) 4 = Some (Z_to_le_bytes 4 d) ->
  store_ok SEGS m (Z_to_bv 64 (s - 96)) 96 = true ->
  getr regs 2 = Z_to_bv 64 s -> getr regs 1 = ret -> getr regs 10 = Z_to_bv 64 pixs -> getr regs 11 = Z_to_bv 64 pup ->
  getr regs 12 = Z_to_bv 64 plf -> getr regs 13 = Z_to_bv 64 prot -> getr regs 14 = Z_to_bv 64 dbg ->
  exists fr' regs',
    msteps SEGS (@mkst (mkFP fr cs) regs (0x9b1c0 : word) m rom) (@mkst (mkFP fr' cs) regs' (0x9b208 : word) (OCF m s ret regs fr) rom)
    /\ getr regs' 2 = Z_to_bv 64 (s - 96) /\ getr regs' 10 = Z_to_bv 64 d /\ getr regs' 8 = Z_to_bv 64 pixs
    /\ getr regs' 9 = Z_to_bv 64 prot /\ getr regs' 18 = Z_to_bv 64 dbg /\ getr regs' 19 = Z_to_bv 64 plf /\ getr regs' 20 = Z_to_bv 64 pup
    /\ regs_agree (fun r => In r [1; 2; 8; 9; 10; 18; 19; 20]%list) regs regs'.
Proof.
