(* [comment removed for export] *)
Lemma oc_D : forall (fx : FPState) regs m (s : Z),
  (96 <= s)%Z -> (s < 2 ^ 64)%Z -> getr regs 2 = Z_to_bv 64 (s - 96) ->
  exists regs',
    msteps SEGS (@mkst fx regs (0x9b24c : word) m rom) (@mkst fx regs' (0x6cb3c : word) m rom)
    /\ getr regs' 1 = Z_to_bv 64 0x9b254 /\ getr regs' 10 = Z_to_bv 64 (s - 88)
