(* [comment removed for export] *)
Lemma oc_S : forall (fx : FPState) regs m (s o ent : Z),
  (96 <= s)%Z -> (s < 2 ^ 64)%Z -> (0 <= o <= 4)%Z -> (0 <= ent < 2 ^ 30)%Z -> ret_ok (Z_to_bv 64 (0x1fc34 + ent)) ->
  rdn SEGS m (Z_to_bv 64 0x1125c8) 8 = Some (Z_to_le_bytes 8 0x1137b8) -> rdn SEGS m (Z_to_bv 64 0x1137b8) 4 = Some (Z_to_le_bytes 4 3) ->
  rdn SEGS m (Z_to_bv 64 (s - 68)) 4 = Some (Z_to_le_bytes 4 o) ->
  rdn SEGS m (Z_to_bv 64 (0x1fc34 + 4 * o)) 4 = Some (Z_to_le_bytes 4 ent) ->
  getr regs 2 = Z_to_bv 64 (s - 96) ->
  exists regs',
    msteps SEGS (@mkst fx regs (0x9b284 : word) m rom) (@mkst fx regs' (Z_to_bv 64 (0x1fc34 + ent)) m rom)
    /\ getr regs' 10 = Z_to_bv 64 3
    /\ regs_agree (fun r => In r [10; 11; 12]%list) regs regs'.
Proof.
