Lemma oc_K2b : forall (fx : FPState) regs m (prot pixs : Z),
  (1 <= prot)%Z -> (prot + 4 <= 2 ^ 64)%Z -> store_ok SEGS m (Z_to_bv 64 prot) 4 = true ->
  getr regs 9 = Z_to_bv 64 prot -> getr regs 8 = Z_to_bv 64 pixs ->
  exists regs', msteps SEGS (@mkst fx regs (0x9b378 : word) m rom) (@mkst fx regs' (0x87798 : word) (wr4 m prot 90) rom)
    /\ getr regs' 1 = Z_to_bv 64 0x9b3c0 /\ getr regs' 10 = Z_to_bv 64 pixs /\ getr regs' 11 = Z_to_bv 64 1
    /\ regs_agree (fun r => In r [1; 10; 11]%list) regs regs'.
Proof.
